CREATE TRIGGER IF NOT EXISTS v270_provider_runtime_readiness_receipt_projection
BEFORE INSERT ON compute_external_pool_adapter_provider_runtime_readiness_receipts
WHEN NEW.readiness_receipt_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness_receipt_id')
 OR NEW.readiness_receipt_schema IS NOT json_extract(NEW.readiness_receipt_json,'$.schema')
 OR NEW.readiness_receipt_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness_receipt_digest')
 OR NEW.readiness_material_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness_material_digest')
 OR NEW.canonicalization IS NOT json_extract(NEW.readiness_receipt_json,'$.canonicalization')
 OR NEW.digest_algorithm IS NOT json_extract(NEW.readiness_receipt_json,'$.digest_algorithm')
 OR NEW.policy_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.policy_id')
 OR NEW.policy_revision IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.policy_revision')
 OR NEW.policy_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.policy_digest')
 OR NEW.provider_binding_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.provider_binding_id')
 OR NEW.provider_binding_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.provider_binding_digest')
 OR NEW.registry_release_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.registry_release_id')
