 OR NEW.registry_release_material_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.registry_release_material_digest')
 OR NEW.installation_receipt_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.installation_receipt_id')
 OR NEW.installation_receipt_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.installation_receipt_digest')
 OR NEW.installation_content_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.installation_content_digest')
 OR NEW.candidate_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.candidate_id')
 OR NEW.candidate_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.candidate_digest')
 OR NEW.delegation_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.delegation_id')
 OR NEW.delegation_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.delegation_digest')
 OR NEW.profile_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.profile_id')
 OR NEW.profile_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.profile_digest')
 OR NEW.target_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.target_id')
 OR NEW.target_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.target_digest')
 OR NEW.companion_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.companion_id')
 OR NEW.companion_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.companion_digest')
 OR NEW.provider_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.provider_id')
 OR NEW.provider_policy_revision IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.provider_policy_revision')
 OR NEW.provider_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.provider_digest')
 OR NEW.provider_status IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.provider_status')
 OR NEW.vulnerability_reattestation_receipt_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.vulnerability_reattestation_receipt_id')
 OR NEW.vulnerability_reattestation_receipt_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.vulnerability_reattestation_receipt_digest')
 OR NEW.sandbox_reattestation_receipt_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.sandbox_reattestation_receipt_id')
 OR NEW.sandbox_reattestation_receipt_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.sandbox_reattestation_receipt_digest')
 OR NEW.credential_reattestation_receipt_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.credential_reattestation_receipt_id')
 OR NEW.credential_reattestation_receipt_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.credential_reattestation_receipt_digest')
 OR NEW.runtime_compatibility_verification_receipt_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.runtime_compatibility_verification_receipt_id')
 OR NEW.runtime_compatibility_verification_receipt_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.runtime_compatibility_verification_receipt_digest')
 OR NEW.launch_policy_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.launch_policy_digest')
