 OR NEW.source_capsule_sha256 IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.source_capsule_sha256')
 OR NEW.source_capsule_size_bytes IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.source_capsule_size_bytes')
 OR NEW.launch_image_sha256 IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.launch_image_sha256')
 OR NEW.launch_image_size_bytes IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.launch_image_size_bytes')
 OR NEW.runtime_custody_epoch_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.sealed_bindings.runtime_custody_epoch_digest')
 OR NEW.runtime_bundle_identity_commitment IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.sealed_bindings.runtime_bundle_identity_commitment')
