 OR NEW.request_bytes IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.request_bytes')
 OR NEW.response_bytes IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.response_bytes')
 OR NEW.probe_checked_at IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.probe_checked_at')
 OR NEW.cleanup_completed_at IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.cleanup_completed_at')
 OR NEW.checked_at IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.checked_at')
 OR NEW.expires_at IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.expires_at')
 OR NEW.sequence IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.sequence')
 OR NEW.predecessor_readiness_receipt_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.predecessor_readiness_receipt_id')
 OR NEW.predecessor_readiness_receipt_digest IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.predecessor_readiness_receipt_digest')
 OR NEW.recorded_by_actor_kind IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.recorded_by_actor_kind')
 OR NEW.recorded_by_actor_user_id IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.recorded_by_actor_user_id')
 OR NEW.recorded_at IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.recorded_at')
 OR NEW.idempotency_scope IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.idempotency_scope')
 OR NEW.idempotency_key IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.idempotency_key')
 OR NEW.confirmation IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.confirmation')
 OR NEW.evidence_scope IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.evidence_scope')
 OR NEW.receipt_status IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.receipt_status')
 OR NEW.effects_json IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.effects')
 OR NEW.observed_readiness_json IS NOT json_extract(NEW.readiness_receipt_json,'$.readiness.observed_readiness')
BEGIN SELECT RAISE(ABORT,'V270 readiness scalar projection mismatch'); END;

CREATE TRIGGER IF NOT EXISTS v270_provider_runtime_readiness_revocation_projection
