 OR NEW.confirmation IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.confirmation')
 OR NEW.revocation_status IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.revocation_status')
 OR NEW.effects_json IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.effects')
 OR NEW.readiness_json IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.readiness')
